411	                                    let current_view = window.current_view();
412	                                    let task = window.spawn(cx, async move |cx| {
413	                                        cx.background_executor().timer(LOADING_DELAY).await;
414	                                        cx.update(move |_, cx| {
415	                                            cx.notify(current_view);
416	                                        })
417	                                        .ok();
418	                                    });
